import{_ as o,o as r,c as a,a5 as t}from"./chunks/framework.BZzouRtU.js";const d="/study/images/browser/audio-convolution-paths.svg",i="/study/images/browser/audio-convolution-overlap.svg",f=JSON.parse('{"title":"Web Audioの畳み込みリバーブ — インパルス応答から響きを作る","description":"","frontmatter":{"title":"Web Audioの畳み込みリバーブ — インパルス応答から響きを作る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"音に対する部屋の応答をサンプル列で表し、入力に合わせてずらして足すと残響を作れる。ConvolverNodeで処理し、元の音と響きを別々に調整する仕組みを解説する。","aliases":["Web Audio API","畳み込み","畳み込みリバーブ","convolution reverb","インパルス応答","impulse response","IR","ConvolverNode","残響","初期反射","ドライ","ウェット"],"verification":"W3C Web Audio APIのConvolverNodeとJulius O. SmithのIntroduction to Digital Filtersに照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-convolution-reverb.md","filePath":"browser/audio-convolution-reverb.md"}'),n={name:"browser/audio-convolution-reverb.md"};function s(l,e,c,u,h,p){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="web-audioの畳み込みリバーブ-—-インパルス応答から響きを作る" tabindex="-1">Web Audioの畳み込みリバーブ — インパルス応答から響きを作る <a class="header-anchor" href="#web-audioの畳み込みリバーブ-—-インパルス応答から響きを作る" aria-label="Permalink to &quot;Web Audioの畳み込みリバーブ — インパルス応答から響きを作る&quot;">​</a></h1><p>フィードバックディレイは音をループに戻し、一定の間隔で繰り返します。部屋では壁や天井からの反射が異なる時刻に届き、いくつもの経路を通った音が重なります。短い刺激に対して届く音を<strong>インパルス応答</strong>（IR）として表すと、別の音にもその響きを加えられます。<a href="/study/browser/audio-feedback-delay.html">フィードバックディレイ</a>、<a href="https://www.w3.org/TR/webaudio/#ConvolverNode" target="_blank" rel="noreferrer">W3C Web Audio APIのConvolverNode</a></p><h2 id="部屋の響きを波形にする" tabindex="-1">部屋の響きを波形にする <a class="header-anchor" href="#部屋の響きを波形にする" aria-label="Permalink to &quot;部屋の響きを波形にする&quot;">​</a></h2><p>音源とマイクの位置を決めて部屋のインパルス応答を測ると、音源から直接届いた音に続いて、壁などを経由した<strong>初期反射</strong>が現れます。その後は多くの反射が重なり、全体として弱くなっていきます。この応答には部屋の形や材質のほか、音源とマイクの位置も反映されます。測定には、周波数を連続的に変えた信号をスピーカーから流し、録音からインパルス応答を求める方法もあります。<a href="https://www.dsprelated.com/freebooks/pasp/Artificial_Reverberation.html" target="_blank" rel="noreferrer">Julius O. Smithの人工残響</a>、<a href="https://angelofarina.it/Public/Papers/134-AES00.PDF" target="_blank" rel="noreferrer">Angelo Farinaのスイープ信号による測定</a></p><p>実践では、初期反射と減衰する尾をコードで作った2種類のIRを使います。IRに直接音を含めず、別の経路で元の音（ドライ）を加えます。響きだけの音（ウェット）にかけるゲインを変えると、ドライ経路の振幅を保ったまま残響の量を調整できます。直接音を含んだ実測のIRで同じように重ねると、直接成分も足し合わさります。<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシングとヘッドルーム</a></p><figure class="study-figure"><img src="'+d+'" alt="入力を二つに分ける。ドライ経路は入力をそのまま、ウェット経路はインパルス応答との畳み込みにゲインを掛け、最後に二つを足す。" width="760" height="404" loading="lazy"><figcaption>響きだけを別の経路に置くと、元の音にどれだけ加えるかを調整できます。<a href="/study/images/browser/audio-convolution-paths.svg" target="_blank" rel="noopener noreferrer">ドライとウェットの経路を拡大</a></figcaption></figure><h2 id="入力のサンプルごとに応答をずらして足す" tabindex="-1">入力のサンプルごとに応答をずらして足す <a class="header-anchor" href="#入力のサンプルごとに応答をずらして足す" aria-label="Permalink to &quot;入力のサンプルごとに応答をずらして足す&quot;">​</a></h2><p>IRを <code>h[k]</code>、入力を <code>x[n]</code> とします。時刻 <code>n</code> に値 <code>x[n]</code> があると、そのサンプルの寄与として、IRを <code>n</code> サンプルずらして <code>x[n]</code> 倍した波形が加わります。すべての入力サンプルの寄与を重ねる演算が<strong>畳み込み</strong>です。IRが <code>M</code> サンプルなら、出力 <code>y[n]</code> は同じ計算を次の形で表せます。入力の範囲外は0とします。<a href="https://www.dsprelated.com/freebooks/filters/Convolution_Representation.html" target="_blank" rel="noreferrer">Julius O. Smithの畳み込みの導出</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y[n] = Σ (h[k] × x[n − k])    k = 0 … M − 1</span></span></code></pre></div><p>例えば <code>x = [1, 0.5]</code> と <code>h = [0.6, 0.3, 0.15]</code> では、時刻0の入力から <code>[0.6, 0.3, 0.15, 0]</code>、時刻1の入力から <code>[0, 0.3, 0.15, 0.075]</code> が生じます。重なった値を足すと <code>[0.6, 0.6, 0.3, 0.075]</code> です。時刻1の出力 <code>0.6</code> には、時刻0に入ったサンプルの遅れた成分 <code>0.3</code> と、時刻1に入ったサンプルからの成分 <code>0.3</code> が含まれています。</p><figure class="study-figure"><img src="'+i+'" alt="入力の1番目から0.6、0.3、0.15、0が生じる。入力の2番目から1サンプルずれた0、0.3、0.15、0.075が生じる。列ごとの合計は0.6、0.6、0.3、0.075。" width="760" height="416" loading="lazy"><figcaption>IRを入力の時刻に合わせてずらし、同じ時刻に届く成分を足します。<a href="/study/images/browser/audio-convolution-overlap.svg" target="_blank" rel="noopener noreferrer">サンプルごとの畳み込みを拡大</a></figcaption></figure><p>入力が <code>N</code> サンプル、IRが <code>M</code> サンプルあると、線形畳み込みの出力は <code>N + M − 1</code> サンプルです。最後に入った音からも遅れて届く成分があるため、入力が止まったあとに響きが残ります。インパルスとして <code>[1]</code> だけを入力すると、出力は <code>h</code> そのものになります。<a href="https://www.dsprelated.com/freebooks/sasp/Convolution_Short_Signals.html" target="_blank" rel="noreferrer">Julius O. Smithの短い信号の畳み込み</a></p><h2 id="convolvernodeにインパルス応答を渡す" tabindex="-1">ConvolverNodeにインパルス応答を渡す <a class="header-anchor" href="#convolvernodeにインパルス応答を渡す" aria-label="Permalink to &quot;ConvolverNodeにインパルス応答を渡す&quot;">​</a></h2><p><code>ConvolverNode.buffer</code> にIRを <code>AudioBuffer</code> として設定します。バッファのサンプルレートはコンテキストに合わせます。仕様上、IRのチャンネル数は1、2、4のいずれかで、実践ではモノラルの入力とモノラルのIRを使います。<code>normalize</code> の既定値は <code>true</code> で、IRごとの出力レベルの差を抑えるためにIRをスケーリングします。バッファに書いた係数で畳み込む場合は、<code>normalize = false</code> を <code>buffer</code> に代入する前に設定します。<a href="https://www.w3.org/TR/webaudio/#ConvolverNode" target="_blank" rel="noreferrer">W3C Web Audio APIのConvolverNode</a></p><p>畳み込みの式をそのまま計算すると、長いIRでは出力サンプルごとの積和が増えます。実装によってはIRを分割してFFTで周波数領域へ移し、掛け算した結果を時間領域に戻して重ねます。Web Audioの仕様が定めるのは線形畳み込みの結果です。処理方法はブラウザの実装に委ねられます。<a href="https://www.dsprelated.com/freebooks/mDFT/Convolution_Theorem.html" target="_blank" rel="noreferrer">Julius O. Smithの畳み込み定理</a>、<a href="https://aes.org/publications/elibrary-page/?id=6335" target="_blank" rel="noreferrer">William G. GardnerのブロックFFTを用いる畳み込み</a></p><h2 id="ゲームの空間ごとに響きを変える" tabindex="-1">ゲームの空間ごとに響きを変える <a class="header-anchor" href="#ゲームの空間ごとに響きを変える" aria-label="Permalink to &quot;ゲームの空間ごとに響きを変える&quot;">​</a></h2><p>例えば、プレイヤーが通路から広いホールへ入るとき、足音をホール用のIRへ送る量を増やせます。この送り出しを<strong>センド</strong>と呼びます。元の音には距離による音量や方向を適用し、残響経路では空間の響きを加えます。IRを再生中に差し替えると不連続が生じることがあるため、空間の境目では別の <code>ConvolverNode</code> を用意し、両方の響きを重ねながら切り替える方法があります。<a href="https://www.w3.org/TR/webaudio/#ConvolverNode" target="_blank" rel="noreferrer">W3C Web Audio APIのConvolverNode</a>、<a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a></p><h2 id="ブラウザで残響の始まりと尾を比べる" tabindex="-1">ブラウザで残響の始まりと尾を比べる <a class="header-anchor" href="#ブラウザで残響の始まりと尾を比べる" aria-label="Permalink to &quot;ブラウザで残響の始まりと尾を比べる&quot;">​</a></h2><p>実践では <code>OfflineAudioContext</code> と <code>ConvolverNode</code> でウェット信号を生成し、サンプル値にゲインを掛けてドライ信号に加えます。小部屋を想定したIRでは12 ms、ホールを想定したIRでは40 msで最初の反射が始まります。同じ打音を使い、IRを切り替えたときの波形と聴こえ方を比べます。<a href="/study/practice/browser/audio-reverb-observation.html">畳み込みリバーブの実践</a>、<a href="https://www.w3.org/TR/webaudio/#OfflineAudioContext" target="_blank" rel="noreferrer">W3C Web Audio APIのOfflineAudioContext</a></p><p>ゲーム内で音源や聞き手が動くときは、直接音の方向と距離も変わります。位置に応じて左右の出力を決める仕組みと、耳に届く音の変化を畳み込みで表すHRTFを扱います。<a href="/study/browser/audio-spatial-panning.html">Web Audioの音の定位と距離減衰</a></p>',20)])])}const v=o(n,[["render",s]]);export{f as __pageData,v as default};
